<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $rows @var string $state @var bool $canWrite @var bool $finance @var array $states */
require __DIR__ . '/_nav.php'; ?>
<div class="sr-filter"><?php foreach (array_merge([''], $states) as $s): ?><a class="btn sm <?= $s === $state ? 'primary' : '' ?>" href="<?= e($sf->url('/contracts' . ($s !== '' ? '?state=' . $s : ''))) ?>"><?= e($s === '' ? $sf->t('all_statuses') : $sf->t('st_' . $s)) ?></a><?php endforeach; ?>
  <?php if ($canWrite): ?><a class="btn primary" href="<?= e($sf->url('/contract/0/edit')) ?>">+ <?= e($sf->t('contract_new')) ?></a><?php endif; ?></div>
<?php if (!$rows): ?><div class="card empty"><?= e($sf->t('none')) ?></div><?php else: ?>
<div class="card sr-scroll"><table><thead><tr><th><?= e($sf->t('col_contract')) ?></th><th><?= e($sf->t('col_tenant')) ?></th><th><?= e($sf->t('col_units')) ?></th><th><?= e($sf->t('col_period')) ?></th><th><?= e($sf->t('col_rate')) ?></th><th><?= e($sf->t('col_monthly')) ?></th><th><?= e($sf->t('col_status')) ?></th></tr></thead><tbody>
<?php foreach ($rows as $k): ?><tr><td><a href="<?= e($sf->url('/contract/' . $k['id'])) ?>"><b><?= e($k['number']) ?></b></a></td><td><a href="<?= e($sf->url('/tenant/' . $k['tenant_id'])) ?>"><?= e($k['tenant']['name'] ?? '') ?></a><?php if (($k['tenant']['restrictions'] ?? '') !== ''): ?> <span class="badge warn" title="<?= e($k['tenant']['restrictions']) ?>">!</span><?php endif; ?></td>
  <td><?= e(implode(', ', array_map(fn($l) => ($l['unit']['name'] ?? '') . ((float)$l['share_pct'] < 100 ? ' ' . sr_num($l['share_pct']) . '%' : ''), $k['lines']))) ?></td><td><?= e(sr_d($k['start_date'])) ?> – <?= e(sr_d($k['end_date'])) ?></td>
  <td><?= e(sr_m($k['rate'], $lang)) ?> / <?= e($sf->t('rt_' . $k['rate_type'])) ?></td><td><?= e(sr_m($k['monthly'], $lang)) ?></td><td><span class="badge <?= e(sr_cls($k['state'])) ?>"><?= e($sf->t('st_' . $k['state'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
